// 第七批：神灵庙的复苏者、山门的问候与云上的来客。
window.CHARACTERS.push(
  {id:'miko',batch:'07',name:'丰聪耳神子',jp:'豊聡耳 神子',en:'Toyosatomimi no Miko',title:'圣德道士',species:'圣人（尸解仙）',place:'仙界',group:'tao',color:'#9476a4',ability:'同时听取十个人的对话程度的能力',keywords:'みこ 太子 圣人 道教 神灵庙 十欲 笏板',intro:'高高翘起的发梢，手中从容轻执的笏板。她聆听许多人的话语与欲望，也重新打量漫长沉睡后的世界。',story:'在《东方神灵庙》第六关登场的圣人，拥有同时听取十个人对话的能力。她向青娥学习道教，并以尸解之法等待复苏；布都与屠自古是与她同行的旧日伙伴。复苏后在仙界活动，也在后续作品中参与围绕信仰与人心的较量。角色借用了圣德太子的传说意象，不能直接等同于历史人物传记。',motif:'金棕短发与上翘发束 · 紫色披风 · 笏板',relation:'布都与屠自古侍奉她；曾向青娥学习道教。',source:'c024'},
  {id:'futo',batch:'07',name:'物部布都',jp:'物部 布都',en:'Mononobe no Futo',title:'古代日本的尸解仙',species:'人类（自称尸解仙）',place:'仙界',group:'tao',color:'#6f907c',ability:'操纵风水程度的能力',keywords:'ふと 道士 乌帽 马尾 皿 盘子 神灵庙',intro:'乌帽立起，银色长马尾随着宽袖轻晃。一只瓷皿与一份古风的自信，陪她重新认识千年后的幻想乡。',story:'《东方神灵庙》第五关的对手，追随神子接受尸解之法。她以操纵风水的能力战斗，原作弹幕与后续格斗作品中都能看到舟、火与皿等意象。她的举止与说话方式保留古风，对新时代的理解也带来独特趣味。资料中的种族表述保留“人类（自称尸解仙）”，不把称号当作毫无差别的种族分类。',motif:'银灰高马尾 · 黑色乌帽 · 白衣绿裙与瓷皿',relation:'追随神子，与屠自古同为其身边的伙伴。',source:'c038'},
  {id:'tojiko',batch:'07',name:'苏我屠自古',jp:'蘇我 屠自古',en:'Soga no Tojiko',title:'神明后裔的亡灵',species:'亡灵',place:'仙界',group:'tao',color:'#68866b',ability:'引发雷电程度的能力',keywords:'とじこ 绿发 卷发 亡灵 雷电 神灵庙',intro:'卷曲绿发下是藏不住的直率，裙摆下浮着两缕灵体。雷光微微一闪，旧日的伙伴又在叫她一起行动。',story:'在《东方神灵庙》第五关道中登场，也出现在神子的战斗中。她与布都一同侍奉神子，以亡灵形态行动，拥有引发雷电的能力。关于尸解与舍弃肉体的来由，不同原作叙述各有视角；本册先保留她如今的身份与伙伴关系，不另编家族或婚姻设定。',motif:'绿色短卷发 · 黑帽与垂纸 · 深绿衣裙与双灵尾',relation:'与布都一起侍奉神子，以不同的形态迎来复苏后的世界。',reference:'https://thwiki.cc/苏我屠自古'},
  {id:'seiga',batch:'07',name:'霍青娥',jp:'霍 青娥',en:'Seiga Kaku',title:'穿墙的邪仙',species:'邪仙',place:'仙界与墓地一带',group:'tao',color:'#6e8eae',ability:'穿越墙壁程度的能力',keywords:'せいが 青娥娘娘 道教 穿墙 环形发髻 凿子 神灵庙',intro:'环形发髻与白色羽衣，勾出一位含笑的仙人。看起来温和的她，总能从墙壁与规矩之间找到自己的去路。',story:'《东方神灵庙》第四关的对手，向往道教、修行成仙，也曾将道教传给神子。她能穿越墙壁，并以符札操纵僵尸芳香。温和的外表不等于善良无害的行事准则，“邪仙”也是理解她的重要一面。画中相伴的两人是操纵者与僵尸的关系，不另写成亲属。',motif:'深蓝卷发与环形发髻 · 凿形发簪 · 白色羽衣',relation:'芳香的操纵者，曾向神子传授道教。',reference:'https://touhougarakuta.com/article/chara-seiga/'},
  {id:'yoshika',batch:'07',name:'宫古芳香',jp:'宮古 芳香',en:'Yoshika Miyako',title:'忠实的僵尸',species:'僵尸',place:'墓地一带',group:'tao',color:'#ae686b',ability:'无所不吃程度的能力',keywords:'よしか 僵尸 符纸 青娥 墓地 神灵庙',intro:'额前符纸轻轻垂下，僵直的手臂仍认真守着入口。她按青娥的指令行动，简单的反应里也留下难读的过去。',story:'《东方神灵庙》第三关的对手，是青娥操纵的僵尸，负责阻挡进入墓地深处的人。她拥有无所不吃的能力，身体僵硬，行动与思考都与普通人不同。她的守卫工作将调查者引向下一关的青娥；在寺院附近登场，并不代表她属于命莲寺的修行者。',motif:'深色短发 · 蓝帽与额前符纸 · 红色盘扣上衣',relation:'受青娥操纵，在神灵庙的调查途中看守入口。',reference:'https://thwiki.cc/宫古芳香'},
  {id:'kyouko',batch:'07',name:'幽谷响子',jp:'幽谷 響子',en:'Kyouko Kasodani',title:'诵经的山彦',species:'山彦',place:'命莲寺',group:'village',color:'#82906c',ability:'反射声音程度的能力',keywords:'きょうこ 响子 回声 兽耳 扫帚 鸟兽伎乐 神灵庙',intro:'扫帚停在石阶边，问候声已经响过山门。会反射声音的山彦，正把命莲寺的清晨过得格外精神。',story:'《东方神灵庙》第二关登场的山彦，能够反射声音。在回声逐渐被人当作自然现象的时代，她来到命莲寺、皈依佛门，承担打扫等日常工作。她还与夜雀米斯蒂娅组成朋克摇滚组合“鸟兽伎乐”；山门的问候与舞台的歌声，是认识她的两条线索。',motif:'绿色短发 · 棕色垂耳 · 扫帚与红色衣裙',relation:'在白莲所在的命莲寺修行，与米斯蒂娅组成鸟兽伎乐。',reference:'https://thwiki.cc/幽谷响子'},
  {id:'tenshi',batch:'07',name:'比那名居天子',jp:'比那名居 天子',en:'Tenshi Hinanawi',title:'非想非非想天之女',species:'天人',place:'天界',group:'heaven',color:'#6a95b0',ability:'操纵大地程度的能力',keywords:'てんし 桃子 要石 绯想之剑 地震 绯想天',intro:'帽上的桃子映着云光，长蓝发随风展开。天界的悠闲让她坐不住，地上的异变也曾从这份任性开始。',story:'在《东方绯想天》中登场的天人，拥有操纵大地的能力。她随家族升入天界，对平静生活感到无聊，带着要石与绯想之剑介入地上的事件。天气异常与地震线索，把各路人物引向云上的来客。她的任性、好胜与后续经历，可以沿不同作品继续阅读。',motif:'蓝色长发 · 桃饰黑帽 · 绯想之剑与虹色裙边',relation:'在绯想天的异变中与衣玖及地上的调查者相遇。',source:'c035'},
  {id:'iku',batch:'07',name:'永江衣玖',jp:'永江 衣玖',en:'Iku Nagae',title:'美丽的绯色之衣',species:'妖怪（龙宫使者）',place:'云海',group:'heaven',color:'#8e789f',ability:'解读空气程度的能力',keywords:'いく 羽衣 龙宫 使者 绯想天 雷电 红绸',intro:'绯边羽衣顺着云风浮动，短卷发下是安静的目光。她留意龙神的话语，把重要的预兆带给地上的人们。',story:'《东方绯想天》中登场的龙宫使者，生活在人类世界与龙的世界之间。她能够听懂龙的声音，并把重要的信息传达出来；地震的预告是故事里的关键线索。“解读空气”也涉及顺应周围环境，不能只理解成人际场合的察言观色。她与天子有交集，但并非天子的专属女仆。',motif:'蓝紫短卷发 · 长红缎帽饰 · 绯边白色羽衣',relation:'传递龙神的重要消息，在绯想天中与天子等人相遇。',reference:'https://thwiki.cc/永江衣玖'}
);
// 第八批：辉针城的湖畔来客、乐器付丧神与逆城中的小小身影。
window.CHARACTERS.push(
  {id:'wakasagihime',batch:'08',name:'若鹭姬',jp:'わかさぎ姫',en:'Wakasagihime',title:'栖息于淡水的人鱼',species:'人鱼',place:'雾之湖',group:'lake',color:'#709994',ability:'在水中力量会增加程度的能力',keywords:'わかさぎひめ 人鱼 若鹭 鱼尾 辉针城 石头',intro:'蓝色短卷发下，鱼鳍般的耳朵轻轻展开。她把湖水当作日常，也会为一块漂亮的小石头停下歌声。',story:'生活在雾之湖的淡水人鱼，在《东方辉针城》第一关登场。她平日唱歌、捡拾石头，与影狼是朋友；万宝槌逸散的魔力曾让她卷入骚动。她在水中力量会增强，不能仅因登场关卡靠前，就把她写成任何场合都弱小的角色。',motif:'深蓝短发与鬓边卷发 · 鱼鳍耳 · 浅蓝鱼尾',relation:'与今泉影狼交好，生活在雾之湖。',reference:'https://touhougarakuta.com/article/chara-wakasagi-hime/'},
  {id:'sekibanki',batch:'08',name:'赤蛮奇',jp:'赤蛮奇',en:'Sekibanki',title:'辘轳首的怪奇',species:'辘轳首',place:'人类村落一带',group:'night',color:'#a8504b',ability:'让头飞出去程度的能力',keywords:'せきばんき 飞头蛮 红发 披风 柳之运河 辉针城',intro:'红发、蓝色缎带，还有藏住脖子的高高衣领。她在人类之间安静生活，也有不愿轻易合群的骄傲。',story:'《东方辉针城》第二关的对手，平时混在人类之间生活。与普通伸长脖子的辘轳首不同，她能让头部离开身体飞行，兼有飞头蛮的形象。受到万宝槌影响后，她曾在柳之运河一带骚动。本册插图呈现她日常的完整形态，能力则在文字中说明。',motif:'红色短发 · 蓝色后脑缎带 · 红蓝高领披风',relation:'与调查辉针城异变的主人公在柳之运河相遇。',source:'c041'},
  {id:'kagerou',batch:'08',name:'今泉影狼',jp:'今泉 影狼',en:'Kagerou Imaizumi',title:'竹林的狼人',species:'狼女',place:'迷途竹林',group:'bamboo',color:'#9b7659',ability:'在满月之夜变身为狼程度的能力',keywords:'いまいずみ かげろう 狼耳 长发 月夜 辉针城',intro:'长褐发沿着衣袖落下，尖尖狼耳听见竹林的风。满月会带来变化，却不会让她失去平日的沉着。',story:'独居迷途竹林的狼女，在《东方辉针城》第三关登场。她会在满月之夜变身为狼，即使如此仍能保持冷静，并非一见月亮便丧失理智。她在意变身后增多的毛发，常以长衣遮住皮肤。若鹭姬是她的朋友，两人的来往也让竹林与湖畔有了人物线索。',motif:'及腰褐色长发 · 尖狼耳 · 白红长裙与深色袖口',relation:'与若鹭姬是朋友，在竹林安静生活。',reference:'https://thwiki.cc/今泉影狼'},
  {id:'benben',batch:'08',name:'九十九弁弁',jp:'九十九 弁々',en:'Benben Tsukumo',title:'古琵琶的付丧神',species:'付丧神',place:'活动地点未明确',group:'instruments',color:'#9b83a6',ability:'自行发声演奏程度的能力',keywords:'つくも べんべん 琵琶 姐妹 低双马尾 辉针城',intro:'淡紫色长发分作低低的双马尾，四根光弦从古琵琶上延伸。她以从容的节拍，回应自己刚刚获得的声音。',story:'由古琵琶产生自我意识的付丧神，与八桥在《东方辉针城》第四关登场，也在 Extra 关卡中出现。她扮演较成熟的姐姐角色，但两人只是同时成为妖怪，并无血缘关系。万宝槌的魔力让她们觉醒；雷鼓后来传授了更换魔力来源的方法，使她们得以继续存在。',motif:'淡紫低双马尾 · 白花发饰 · 古琵琶与发光琴弦',relation:'与八桥以姐妹相称，受过雷鼓的帮助。',reference:'https://thwiki.cc/九十九弁弁'},
  {id:'yatsuhashi',batch:'08',name:'九十九八桥',jp:'九十九 八橋',en:'Yatsuhashi Tsukumo',title:'古琴的付丧神',species:'付丧神',place:'活动地点未明确',group:'instruments',color:'#94769e',ability:'自行发声演奏程度的能力',keywords:'つくも やつはし 古琴 姐妹 发箍 琴弦 辉针城',intro:'棕色短发配着折线发箍，指尖拨动悬在身前的光弦。脱离器物的束缚之后，她正热热闹闹地学习自由。',story:'古琴化成的付丧神，在《东方辉针城》中与弁弁共同出场。她扮演好胜活泼的妹妹角色，却不是弁弁的血亲。最初的下克上想法受到万宝槌魔力影响；异变之后，她们在雷鼓帮助下寻找新的魔力来源。她的视觉重点是琴弦与演奏动作，不把她的乐器改画成吉他。',motif:'棕色短发 · 紫色折线发箍 · 指套与悬浮琴弦',relation:'与弁弁同期觉醒，并从雷鼓那里获得继续存在的方法。',reference:'https://thwiki.cc/九十九八桥'},
  {id:'seija',batch:'08',name:'鬼人正邪',jp:'鬼人 正邪',en:'Seija Kijin',title:'逆袭的天邪鬼',species:'天邪鬼',place:'辉针城等处',group:'castle',color:'#a35a61',ability:'翻转一切程度的能力',keywords:'きじん せいじゃ 小角 挑染 箭头 逆转 下克上 天邪鬼',intro:'黑发间挑出红白两色，箭头纹样朝着不同方向。她偏爱把事情反过来看，也把反抗本身当作乐趣。',story:'《东方辉针城》第五关的天邪鬼，煽动针妙丸使用万宝槌，企图颠覆幻想乡的强弱秩序。她的反叛并不自动等同于无私帮助弱者；欺骗与恶意也是原作塑造的一部分。在《弹幕天邪鬼》中，她成为使用反则道具应对追捕的主角。',motif:'黑发中的红白挑染 · 两只小角 · 上下箭头纹样',relation:'曾煽动并利用针妙丸，之后的来往应结合具体作品阅读。',source:'c026'},
  {id:'shinmyoumaru',batch:'08',name:'少名针妙丸',jp:'少名 針妙丸',en:'Shinmyoumaru Sukuna',title:'小人的末裔',species:'小人',place:'辉针城等处',group:'castle',color:'#ad6a76',ability:'使用万宝槌程度的能力',keywords:'すくな しんみょうまる 针妙丸 一寸法师 小槌 碗 辉针城',intro:'一只漆碗、一根缝针，还有高高举起的小槌。身形小小，愿望却有自己的重量，也曾因此被别人的话打动。',story:'一寸法师后裔的小人，在《东方辉针城》第六关登场，能够使用秘宝万宝槌。受到正邪编造的历史与煽动影响，她发动了异变，逸散魔力又影响到其他妖怪和道具。万宝槌有代价，她的体型也会随魔力状况变化；不能把图中的比例当作永远固定的身高。',motif:'淡紫短发 · 漆碗帽与碗舟 · 缝针与万宝槌',relation:'与正邪共同卷入辉针城异变，之后也曾受灵梦照看。',source:'c027'},
  {id:'raiko',batch:'08',name:'堀川雷鼓',jp:'堀川 雷鼓',en:'Raiko Horikawa',title:'梦幻的打击乐手',species:'付丧神',place:'各处演奏活动',group:'instruments',color:'#ae6656',ability:'让一切跟上节奏程度的能力',keywords:'ほりかわ らいこ 鼓棒 电子鼓 白西装 节拍 辉针城',intro:'红色短卷发随着节拍轻轻摆动，白西装里装着果断的主意。她敲响鼓面，也为新生的伙伴找到继续发声的方法。',story:'《东方辉针城》Extra 关卡的付丧神，原本与和太鼓有关。察觉万宝槌魔力的影响后，她冒险寻得外界新的鼓身与演奏者，摆脱了对原有魔力的依赖，并将方法传给九十九姐妹等付丧神。后来她也参加与骚灵三姐妹的乐团活动，电子鼓与现代衣装构成鲜明轮廓。',motif:'红色短卷发 · 白色西装 · 鼓棒与六角鼓面',relation:'帮助弁弁与八桥，并在后续作品中与骚灵乐团合作。',reference:'https://thwiki.cc/堀川雷鼓'}
);

// 第九批：骚灵乐团、报春妖精与妖怪之山的四张新面孔。
